{
  "name": "Rinaldo Torquato Advogado Tributário",
  "description": "Site institucional para escritório de advocacia especializado em isenção de Imposto de Renda para aposentados com doença grave.",
  "requestFramePermissions": []
}

import React from 'react';
import { FileText, Stethoscope, History, Scale, TrendingUp } from 'lucide-react';
import { GuidanceItem } from '../types';

const guidanceItems: GuidanceItem[] = [
  {
    id: 1,
    title: 'Como funciona a isenção?',
    summary: 'A isenção é um direito previsto no Art. 6º, inciso XIV, da Lei nº 7.713/88. É necessário preencher dois requisitos: 1. Estar aposentado; 2. Possuir uma das doenças previstas no rol legal, apresentando documentos médicos comprobatórios.',
    iconName: 'FileText'
  },
  {
    id: 2,
    title: 'Preciso de laudo oficial?',
    summary: 'Não. Conforme a Súmula 598 do STJ, é possível o reconhecimento da isenção mesmo sem laudo oficial, desde que o conjunto probatório (exames, atestados, tomografias) seja robusto para comprovar a doença.',
    iconName: 'Stethoscope'
  },
  {
    id: 3,
    title: 'Dinheiro de volta (5 Anos)',
    summary: 'Sim, é possível recuperar valores pagos ou retidos na fonte dos últimos 5 (cinco) anos. Esse "crédito tributário" volta para o seu bolso com correção monetária (Taxa Selic).',
    iconName: 'History'
  },
  {
    id: 4,
    title: 'Diferença: Isenção vs Imunidade',
    summary: 'Imunidade é limitação constitucional ao poder de tributar. Isenção é dispensa legal do pagamento. Aposentados com doença grave têm isenção legal conforme a Lei 7.713/88.',
    iconName: 'Scale'
  }
];

const getIcon = (name: string) => {
  switch (name) {
    case 'FileText': return <FileText className="w-8 h-8 text-accent" />;
    case 'Stethoscope': return <Stethoscope className="w-8 h-8 text-accent" />;
    case 'History': return <TrendingUp className="w-8 h-8 text-green-600" />; // Ícone de gráfico subindo para dinheiro
    case 'Scale': return <Scale className="w-8 h-8 text-accent" />;
    default: return <FileText className="w-8 h-8 text-accent" />;
  }
};

const Guidance: React.FC = () => {
  return (
    <section id="orientacoes" className="py-20 bg-gray-50">
      <div className="container mx-auto px-4 md:px-6">
        <div className="text-center mb-16">
          <span className="text-accent font-semibold tracking-wider text-sm uppercase">Informações Jurídicas</span>
          <h2 className="text-3xl md:text-4xl font-bold text-primary mt-2 font-serif">Orientações Importantes</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {guidanceItems.map((item) => {
             const isHighlight = item.id === 3; // Destaque para o item de dinheiro de volta

             return (
              <div 
                key={item.id} 
                className={`p-8 rounded-xl transition-all duration-300 ${
                  isHighlight 
                    ? 'bg-white border-2 border-green-100 shadow-lg scale-[1.02] relative overflow-hidden' 
                    : 'bg-white shadow-sm hover:shadow-md border border-gray-100'
                }`}
              >
                {isHighlight && (
                  <div className="absolute top-0 right-0 bg-green-100 text-green-800 text-xs font-bold px-3 py-1 rounded-bl-lg">
                    CRÉDITO A RECEBER
                  </div>
                )}

                <div className={`mb-6 w-16 h-16 rounded-lg flex items-center justify-center ${isHighlight ? 'bg-green-50' : 'bg-blue-50'}`}>
                  {getIcon(item.iconName)}
                </div>
                <h3 className="text-xl font-bold text-primary mb-4">{item.title}</h3>
                <p className="text-gray-600 leading-relaxed text-justify">
                  {item.summary}
                </p>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default Guidance;

import React, { useState } from 'react';
import { Plus, Minus } from 'lucide-react';
import { FAQItem } from '../types';

const faqData: FAQItem[] = [
  {
    question: 'Preciso estar aposentado para ter direito à isenção?',
    answer: 'Sim, a isenção prevista no artigo 6º, inciso XIV da Lei 7.713/88, é válida para proventos de aposentadoria. Pensionistas também podem ter direito.'
  },
  {
    question: 'Preciso apresentar laudo médico recente?',
    answer: 'Não necessariamente. A lei não exige contemporaneidade dos sintomas da doença ou que o laudo médico seja atual, bastando comprovar que o aposentado foi acometido pela doença prevista em lei em algum momento da vida.'
  },
  {
    question: 'A isenção vale para rendimentos de trabalho?',
    answer: 'Não. A isenção refere-se especificamente aos proventos de aposentadoria, reforma ou pensão, e não abrange os rendimentos trabalhistas (salários de quem continua trabalhando).'
  },
  {
    question: 'Quanto tempo demora o processo?',
    answer: 'Depende do caso. A via administrativa tende a ser mais rápida, e a judicial varia conforme o tribunal e a complexidade do caso.'
  },
  {
    question: 'Posso pedir valores retroativos?',
    answer: 'Sim. Até 5 anos, conforme prescrição quinquenal da legislação tributária.'
  },
  {
    question: 'O atendimento é online ou presencial?',
    answer: 'O procedimento de atendimento pode ser feito tanto digitalmente (para todo o Brasil) quanto na forma presencial em Cuiabá-MT.'
  }
];

const FAQ: React.FC = () => {
  const [openIndex, setOpenIndex] = useState<number | null>(null);

  const toggleFAQ = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <section id="faq" className="py-20 bg-white">
      <div className="container mx-auto px-4 md:px-6">
        <h2 className="text-3xl md:text-4xl font-bold text-center text-primary mb-12 font-serif">
          Perguntas Frequentes
        </h2>

        <div className="max-w-3xl mx-auto space-y-4">
          {faqData.map((faq, index) => (
            <div 
              key={index} 
              className="border border-gray-200 rounded-lg overflow-hidden transition-all duration-200 hover:border-gray-300"
            >
              <button
                className="w-full flex justify-between items-center p-5 text-left bg-white hover:bg-gray-50 transition-colors"
                onClick={() => toggleFAQ(index)}
              >
                <span className="text-lg font-medium text-primary pr-4">{faq.question}</span>
                {openIndex === index ? (
                  <Minus className="text-accent flex-shrink-0" />
                ) : (
                  <Plus className="text-gray-400 flex-shrink-0" />
                )}
              </button>

              {openIndex === index && (
                <div className="p-5 bg-gray-50 border-t border-gray-100 text-gray-700 leading-relaxed">
                  {faq.answer}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default FAQ;

